            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Truth is the most valuable thing we have. Let us economize it.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "I haven't a particle of confidence in a man who has no redeeming petty vices whatsoever.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "He was ignorant of the commonest accomplishments of youth. He could not even lie.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Soap and education are not as sudden as a massacre, but they are more deadly in the long run.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "He is now fast rising from affluence to poverty.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Barring that natural expression of villainy which we all have, the man looked honest enough.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Formerly, if you killed a man, it was possible that you were insane—but now, if you, having friends and money, kill a man, it is ''evidence'' that you are a lunatic.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Is not this insanity plea becoming rather common? Is it not so common that the reader confidently expects to see it offered in every criminal case that comes before the courts? [...] Really, what we want now, is not laws against crime, but a law against ''insanity''.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Benjamin Franklin did a great many notable things for his country, and made her young name to be honored in many lands as the mother of such a son. It is not the idea of this memoir to ignore that or cover it up. No; the simple idea of it is to snub those pretentious maxims of his, which he worked up with a great show of originality out of truisms that had become wearisome platitudes as early as the dispersion from Babel.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "A baby is an inestimable blessing and bother.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "The funniest things are the forbidden.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "We haven't all had the good fortune to be ladies; we haven't all been generals, or poets, or statesmen; but when the toast works down to the babies, we stand on common ground.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Among the three or four million cradles now rocking in the land are some which this nation would preserve for ages as sacred things, if we could know which ones they are.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Reader, suppose you were an idiot. And suppose you were a member of Congress. But I repeat myself.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Be respectful to your superiors, if you have any.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "The difference between the ''almost right'' word and the ''right'' word is really a large matter—'tis the difference between the lightning-bug and the lightning.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Weather is a literary specialty, and no untrained hand can turn out a good article on it.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "I am opposed to millionaires, but it would be dangerous to offer me the position.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "James Ross Clemens, a cousin of mine, was seriously ill two or three weeks ago in London, but is well now. The report of my illness grew out of his illness; the report of my death was an exaggeration.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "A round man cannot be expected to fit in a square hole right away. He must have time to modify his shape.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Humor is the great thing, the saving thing. The minute it crops up, all our hardnesses yield, all our irritations and resentments flit away and a sunny spirit takes their place.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Get your facts first, and then you can distort them as much as you please.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "I was sorry to have my name mentioned as one of the great authors, because they have a sad habit of dying off. Chaucer is dead, Spencer is dead, so is Milton, so is Shakespeare, and I'm not feeling so well myself.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "He had only one vanity; he thought he could give advice better than any other person.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "There is nothing in the world like a persuasive speech to fuddle the mental apparatus and upset the convictions and debauch the emotions of an audience not practised in the tricks and delusions of oratory.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Why, you simple creatures, the weakest of all weak things is a virtue which has not been tested in the fire.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "It should, it seems to me, be our pleasure and duty to make those people [the Filipinos] free, and let them deal with their own domestic questions in their own way. And so I am an anti-imperialist. I am opposed to having the eagle put its talons on any other land.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Definition of a classic — something that everybody wants to have read and nobody wants to read.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "We believe that out of the public school grows the greatness of a nation.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "The silent colossal National Lie that is the support and confederate of all the tyrannies and shams and inequalities and unfairnesses that afflict the peoples — that is the one to throw bricks and sermons at.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Your race, in its poverty, has unquestionably one really effective weapon—laughter. Power, Money, Persuasion, Supplication, Persecution—these can lift at a colossal humbug,—push it a little—crowd it a little—weaken it a little, century by century: but only Laughter can blow it to rags and atoms at a blast. Against the assault of Laughter nothing can stand.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Whose property is my body? Probably mine. I so regard it. If I experiment with it, who must be answerable? I, not the State. If I choose injudiciously, does the State die? Oh no.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "heaven for climate, Hell for society.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Honesty is the best policy — when there is money in it.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Now what I contend is that my body is my own, at least I have always so regarded it. If I do harm through my experimenting with it, it is I who suffer, not the state.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "The Blessings-of-Civilization Trust, wisely and cautiously administered, is a Daisy. There is more money in it, more territory, more sovereignty, and other kinds of emolument, than there is in any other game that is played. But Christendom has been playing it badly of late years, and must certainly suffer by it, in my opinion. She has been so eager to get every stake that appeared on the green cloth, that the People who Sit in Darkness have noticed it -- they have noticed it, and have begun to show alarm. They have become suspicious of the Blessings of Civilization.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "To create man was a fine and original idea; but to add the sheep was a tautology.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Man has been here 32,000 years. That it took a hundred million years to prepare the world for him is proof that that is what it was done for. I suppose it is, I dunno. If the Eiffel Tower were now representing the world's age, the skin of paint on the pinnacle-knob at its summit would represent man's share of that age; and anybody would perceive that the skin was what the tower was built for. I reckon they would, I dunno.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Belgium's royal palace is still what it has been for the last 14 years: a lair of a wild beast that for its money every year mutilates, murders and starves a half million helpless natives in the Congo Free State.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "To put it in rude, plain, unpalatable words — ''true'' patriotism, real patriotism: loyalty not to a Family and a Fiction, but a loyalty to the Nation itself! Remember this, take this to heart, live by it, die for it if necessary: that our patriotism is medieval, outworn, obsolete; that the modern patriotism, the true patriotism, the only rational patriotism, is ''loyalty to the Nation ALL the time, loyalty to the Government when it deserves it.''", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "He is a stranger to me, but he is a most remarkable man — and I am the other one. Between us, we cover all knowledge; he knows all that can be known, and I know the rest.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "A powerful agent is the right word. Whenever we come upon one of those intensely right words in a book or a newspaper the resulting effect is physical as well as spiritual, and electrically prompt.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Customs do not concern themselves with right or wrong or reason. But they have to be obeyed; one reasons all around them until he is tired, but he must not transgress them, it is sternly forbidden.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Laws are sand, customs are rock. Laws can be evaded and punishment escaped, but an openly transgressed custom brings sure punishment.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "I have been complimented many times and they always embarrass me; I always feel that they have not said enough.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Thunder is good, thunder is impressive; but it is lightning that does the work.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "When even the brightest mind in our world has been trained up from childhood in a superstition of any kind, it will never be possible for that mind, in its maturity, to examine sincerely, dispassionately, and conscientiously any evidence or any circumstance which shall seem to cast a doubt upon the validity of that superstition. I doubt if I could do it myself.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Adam's ''temperament'' was the first command the Deity ever issued to a human being on this planet. And it was the only command Adam would ''never'' be able to disobey. It said, \"Be weak, be water, be characterless, be cheaply persuadable.\" The later command, to let the fruit alone, was certain to be disobeyed. Not by Adam himself, but by his ''temperament'' — which he did not create and had no authority over.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "The easy confidence with which I know another man's religion is folly teaches me to suspect that my own is also.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "You tell me whar a man gits his corn pone, en I'll tell you what his 'pinions is.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "We all do no end of feeling, and we mistake it for thinking. And out of it we get an aggregation which we consider a boon. Its name is public opinion. It is held in reverence. Some think it the voice of God.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Clothes make the man. Naked people have little or no influence on society.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Always acknowledge a fault frankly. This will throw those in authority off their guard and give you opportunity to commit more.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Humor must not professedly teach, and it must not professedly preach, but it must do both if it would live forever. By forever, I mean thirty years.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "A critic never made or killed a book or a play. The people themselves are the final judges. It is their opinion that counts. After all, the final test is truth. But the trouble is that most writers regard truth as their most valuable possession and therefore are most economical in its use.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "It is curious that physical courage should be so common in the world, and moral courage so rare.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "It is not worth while to try to keep history from repeating itself, for man's character will always make the preventing of the repetitions impossible.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Jesus died to save men — a small thing for an immortal to do, & didn't save many, anyway; but if he had been damned for the race that would have been act of a size proper to a god, & would have saved the whole race. However, why should anybody want to save the human race, or damn it either? Does God want its society? Does Satan?", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "A man is never more truthful than when he acknowledges himself a liar.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "I do not take any credit to my better-balanced head because I never went crazy on Presbyterianism. We go too slow for that. You never see us ranting and shouting and tearing up the ground, You never heard of a Presbyterian going crazy on religion. Notice us, and you will see how we do. We get up of a Sunday morning and put on the best harness we have got and trip cheerfully down town; we subside into solemnity and enter the church; we stand up and duck our heads and bear down on a hymn book propped on the pew in front when the minister prays; we stand up again while our hired choir are singing, and look in the hymn book and check off the verses to see that they don't shirk any of the stanzas; we sit silent and grave while the minister is preaching, and count the waterfalls and bonnets furtively, and catch flies; we grab our hats and bonnets when the benediction is begun; when it is finished, we shove, so to speak. No frenzy, no fanaticism --no skirmishing; everything perfectly serene. You never see any of us Presbyterians getting in a sweat about religion and trying to massacre the neighbors. Let us all be content with the tried and safe old regular religions, and take no chances on wildcat.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Wheresoever she was, THERE was Eden.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Principles have no real force except when one is well-fed.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "An injurious lie is an uncommendable thing; and so, also, and in the same degree, is an injurious truth—a fact that is recognized by the law of libel.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "The highest perfection of politeness is only a beautiful edifice, built, from the base to the dome, of ungraceful and gilded forms of charitable and unselfish lying.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Compliments make me vain: & when I am vain, I am insolent & overbearing. It is a pity, too, because I love compliments. I love them even when they are not so. My child, I can live on a good compliment two weeks with nothing else to eat.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "If you pick up a starving dog and make him prosperous, he will not bite you. This is the principal difference between a dog and a man.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Man is a Religious Animal. He is the only Religious Animal. He is the only animal that has the True Religion — several of them. He is the only animal that loves his neighbor as himself and cuts his throat if his theology isn't straight.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "I must have a prodigious quantity of mind; it takes me as much as a week sometimes to make it up.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "They spell it \"Vinci\" and pronounce it \"Vinchy\". Foreigners always spell better than they pronounce.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "I wish Europe would let Russia annihilate Turkey a little--not much, but enough to make it difficult to find the place again without a divining-rod or a diving-bell.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Virtue never has been as respectable as money.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "The people of those foreign countries are very, very ignorant. They looked curiously at the costumes we had brought from the wilds of America. They observed that we talked loudly at table sometimes. They noticed that we looked out for expenses and got what we conveniently could out of a franc, and wondered where in the mischief we came from. In Paris they just simply opened their eyes and stared when we spoke to them in French! We never did succeed in making those idiots understand their own language.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "Travel is fatal to prejudice, bigotry, and narrow-mindedness, and many of our people need it sorely on these accounts. Broad, wholesome, charitable views of men and things cannot be acquired by vegetating in one little corner of the earth all one's lifetime.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "The Erie railroad kills 23 to 46; the other 845 railroads kill an average of one-third of a man each; and the rest of that million, amounting in the aggregate to that appalling figure of 987,631 corpses, die naturally in their beds! You will excuse me from taking any more chances on those beds. The railroads are good enough for me.", Author = "Mark Twain" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Twain", Text = "All men have heard of the Mormon Bible, but few except the \"elect\" have seen it, or, at least, taken the trouble to read it. I brought away a copy from Salt Lake. The book is a curiosity to me, it is such a pretentious affair, and yet so \"slow,\" so sleepy; such an insipid mess of inspiration. It is chloroform in print. If Joseph Smith composed this book, the act was a miracle — keeping awake while he did it was, at any rate. If he, according to tradition, merely translated it from certain ancient and mysteriously-engraved plates of copper, which he declares he found under a stone in an out-of-the-way locality, the work of translating was equally a miracle, for the same reason.", Author = "Mark Twain" },
        };
    }
}